/*
 * Grand Siecle search page (xslt/search.xsl): instantsearch.js + typesense-instantsearch-adapter
 * (versions shipped with the DSE template in html/vendor). Replaces the template's search.js,
 * which pointed at the ACDH Typesense server. The server address and the search-only key are
 * read from js/search-config.js, generated by pyscripts/make_ts_index.py.
 */
(function () {
    'use strict';

    var errorBox = document.getElementById('search-error');

    function showError(message) {
        errorBox.textContent = message;
        errorBox.hidden = false;
    }


    var FACET_LABELS = {
        doc_title: 'Document', date: 'Date', langs: 'Langue', has_note: 'Note marginale',
        persons: 'Personne', places: 'Lieu', orgs: 'Organisation', works: 'Œuvre'
    };

    function facet(container, attribute, options) {
        return instantsearch.widgets.refinementList(Object.assign({
            container: container,
            attribute: attribute,
            limit: 8,
            showMore: true,
            showMoreLimit: 50,
            sortBy: ['count:desc', 'name:asc'],
            templates: {
                showMoreText: function (data) { return data.isShowingMore ? 'Moins' : 'Plus'; },
                searchableNoResults: function () { return 'Aucune valeur.'; }
            },
            cssClasses: { list: 'list-unstyled', count: 'gs-facet-count', checkbox: 'form-check-input me-1', showMore: 'btn btn-sm btn-outline-secondary mt-1', disabledShowMore: 'd-none' }
        }, options || {}));
    }

    function start(config) {
        var adapter = new TypesenseInstantSearchAdapter({
            server: {
                apiKey: config.apiKey,
                nodes: config.nodes,
                cacheSearchResultsForSeconds: 120
            },
            additionalSearchParameters: {
                query_by: 'text_mod,text_orig,lemmas',
                query_by_weights: '4,3,1',
                sort_by: '_text_match:desc,page_n:asc',
                exclude_fields: 'lemmas',
                highlight_affix_num_tokens: 12
            }
        });
        var search = instantsearch({
            indexName: config.collection,
            searchClient: adapter.searchClient,
            routing: true,
            future: { preserveSharedStateOnUnmount: true }
        });

        search.on('error', function (ev) {
            var node = config.nodes[0];
            var detail = ev && ev.error && ev.error.message ? ' (' + ev.error.message + ')' : '';
            showError('Le serveur de recherche ' + node.protocol + '://' + node.host + ':' + node.port +
                ' ne répond pas' + detail + '. Le reste du site fonctionne normalement ; réessayez plus tard.');
        });

        search.addWidgets([
            instantsearch.widgets.configure({ hitsPerPage: 10 }),
            instantsearch.widgets.searchBox({
                container: '#searchbox',
                placeholder: 'Un mot, une expression, un nom… (ex. éloquence, sçavoir, Cicéron)',
                showLoadingIndicator: true,
                cssClasses: { form: 'd-flex gap-2', input: 'form-control form-control-lg', submit: 'btn btn-primary', reset: 'btn btn-outline-secondary' },
                templates: {
                    submit: function () { return 'Rechercher'; },
                    reset: function () { return 'Effacer'; }
                }
            }),
            instantsearch.widgets.stats({
                container: '#stats',
                templates: {
                    text: function (data) {
                        if (!data.nbHits) { return 'Aucune page trouvée'; }
                        return (data.nbHits === 1 ? '1 page trouvée' : data.nbHits.toLocaleString('fr-FR') + ' pages trouvées') +
                            ' en ' + data.processingTimeMS + ' ms';
                    }
                }
            }),
            instantsearch.widgets.currentRefinements({
                container: '#current-refinements',
                transformItems: function (items) {
                    return items.map(function (item) {
                        return Object.assign({}, item, { label: FACET_LABELS[item.attribute] || item.label });
                    });
                },
                cssClasses: { list: 'list-inline mb-0', item: 'list-inline-item', delete: 'btn btn-sm btn-link p-0 ms-1' }
            }),
            instantsearch.widgets.clearRefinements({
                container: '#clear-refinements',
                templates: { resetLabel: function () { return 'Retirer tous les filtres'; } },
                cssClasses: { button: 'btn btn-sm btn-outline-secondary', disabledButton: 'd-none' }
            }),
            instantsearch.widgets.hits({
                container: '#hits',
                cssClasses: { list: 'list-unstyled gs-hits', item: 'gs-hit' },
                templates: {
                    empty: function (results, tools) {
                        return tools.html`<p class="gs-empty">Aucune page ne correspond à « ${results.query} ». Essayez une autre graphie, un lemme ou retirez des filtres.</p>`;
                    },
                    item: function (hit, tools) {
                        var html = tools.html, components = tools.components;
                        var snip = hit._snippetResult || {};
                        var useOrig = snip.text_orig && snip.text_orig.matchedWords.length &&
                            !(snip.text_mod && snip.text_mod.matchedWords.length);
                        var attr = useOrig ? 'text_orig' : 'text_mod';
                        var refs = (hit.entity_refs || []).slice(0, 8).map(function (r) {
                            var i = r.indexOf('|');
                            return { id: r.slice(0, i), label: r.slice(i + 1), type: r.slice(0, r.indexOf('-')) };
                        });
                        return html`<article>
                            <h3 class="gs-hit-title"><a href="${hit.url}">${hit.doc_title}</a></h3>
                            <p class="gs-hit-meta">${hit.author}, ${hit.date} · page ${hit.page_n}${hit.printed ? ' (p. imprimée ' + hit.printed + ')' : ''} · ${useOrig ? 'texte original' : 'texte modernisé'}</p>
                            <p class="gs-hit-snippet">${components.Snippet({ hit: hit, attribute: attr })}</p>
                            ${refs.length ? html`<p class="gs-hit-entities">${refs.map(function (e) {
                                return html`<a class="ent ent-${e.type}" href="${e.id}.html">${e.label}</a> `;
                            })}</p>` : ''}
                        </article>`;
                    }
                }
            }),
            instantsearch.widgets.pagination({
                container: '#pagination',
                padding: 2,
                cssClasses: { list: 'pagination flex-wrap', item: 'page-item', link: 'page-link', selectedItem: 'active', disabledItem: 'disabled' },
                templates: {
                    previous: function () { return '‹ Précédente'; },
                    next: function () { return 'Suivante ›'; },
                    first: function () { return '«'; },
                    last: function () { return '»'; }
                }
            }),
            facet('#rf-doc', 'doc_title'),
            facet('#rf-date', 'date', { sortBy: ['name:asc'] }),
            facet('#rf-lang', 'langs'),
            instantsearch.widgets.toggleRefinement({
                container: '#rf-note',
                attribute: 'has_note',
                on: true,
                templates: { labelText: function () { return 'Seulement les pages avec note marginale'; } },
                cssClasses: { checkbox: 'form-check-input me-1' }
            }),
            facet('#rf-persons', 'persons', { searchable: true, searchablePlaceholder: 'Filtrer les personnes' }),
            facet('#rf-places', 'places', { searchable: true, searchablePlaceholder: 'Filtrer les lieux' }),
            facet('#rf-orgs', 'orgs'),
            facet('#rf-works', 'works', { searchable: true, searchablePlaceholder: 'Filtrer les œuvres' })
        ]);

        // explicit label for the search field (label[for] in the page)
        search.once('render', function () {
            var input = document.querySelector('#searchbox input');
            if (input) { input.id = 'gs-search-input'; input.setAttribute('aria-label', 'Rechercher dans les textes'); }
        });
        search.start();
    }

    // collapse the filters by default on small screens
    if (window.matchMedia && window.matchMedia('(max-width: 991px)').matches) {
        var filters = document.getElementById('gs-filters');
        if (filters) { filters.open = false; }
    }

    var script = document.createElement('script');
    script.src = 'js/search-config.js';
    script.onload = function () {
        if (!window.GS_SEARCH_CONFIG) { showError('Configuration de recherche invalide (js/search-config.js).'); return; }
        try { start(window.GS_SEARCH_CONFIG); } catch (e) { showError('La recherche n’a pas pu démarrer : ' + e.message); }
    };
    script.onerror = function () {
        showError('La recherche n’est pas configurée sur ce site : l’index n’a pas été construit ' +
            '(js/search-config.js absent, voir pyscripts/make_ts_index.py). Le reste du site fonctionne normalement.');
    };
    document.body.appendChild(script);
}());
